// Map whatever column names this file happens to use onto one shape, and
// drop rows that are structurally junk before they reach the API.
//
// The three source files spell the same field four different ways
// ('Full Name', 'worker_name', 'Name', 'name'), and one of them contains a
// repeated header line and a completely blank row. Any incoming file will do
// the same, so the mapping is by alias rather than by exact key.
const alias = {
  name:  ['name', 'full name', 'full_name', 'worker_name', 'candidate', 'contact name'],
  email: ['email', 'email_id', 'email address', 'e-mail', 'mail'],
  phone: ['phone', 'phone number', 'phone_number', 'mobile', 'contact', 'contact number'],
  city:  ['city', 'location', 'base city', 'current city']
};

function pick(row, keys) {
  for (const [rawKey, value] of Object.entries(row)) {
    const key = String(rawKey || '').trim().toLowerCase();
    if (keys.includes(key) && String(value || '').trim() !== '') {
      return String(value).trim();
    }
  }
  return '';
}

const rows = [];
const skipped = [];

$input.all().forEach((item, index) => {
  const raw = item.json;
  const lineNumber = index + 2;   // +1 for the header, +1 for 1-based counting

  const values = Object.values(raw).map(v => String(v == null ? '' : v).trim());
  if (values.every(v => v === '')) {
    skipped.push({ line: lineNumber, reason: 'blank row' });
    return;
  }

  // A header line repeated inside the data: every cell equals its own column
  // name. Left alone it becomes a contact called "Name" living in "City".
  const looksLikeHeader = Object.entries(raw).every(([key, value]) =>
    String(key || '').trim().toLowerCase() === String(value || '').trim().toLowerCase());
  if (looksLikeHeader) {
    skipped.push({ line: lineNumber, reason: 'repeated header row' });
    return;
  }

  const row = {
    name:  pick(raw, alias.name),
    email: pick(raw, alias.email),
    phone: pick(raw, alias.phone),
    city:  pick(raw, alias.city),
    source_line: lineNumber
  };

  if (!row.name && !row.email && !row.phone) {
    skipped.push({ line: lineNumber, reason: 'no name, email or phone' });
    return;
  }

  rows.push(row);
});

// Note what is NOT done here: no phone normalisation, no lowercasing, no
// matching. That logic already exists once, tested, in pipeline/normalize.py.
// Reimplementing it in a Code node would give two subtly different definitions
// of "the same person", and the copy inside n8n is the one nobody tests.
return [{ json: {
  source: $('Webhook: CSV arrives').first().json.headers
    ? ($('Webhook: CSV arrives').first().json.query.filename || 'webhook upload')
    : 'webhook upload',
  rows,
  skipped,
  parsed_count: rows.length,
  skipped_count: skipped.length
} }];

// Build one readable alert. A 40-row JSON dump in Slack gets muted within a
// week, so the message leads with the counts and names at most five examples.
const data = $json;
const duplicates = data.results.filter(r => r.status === 'duplicate');
const review = data.results.filter(r => r.status === 'needs_review');

function describe(row) {
  const who = row.normalised.name || row.input.name || '(no name)';
  const key = row.matched_on ? ` on ${row.matched_on}` : '';
  const person = row.person_id ? ` -> existing person #${row.person_id} ${row.person_name}` : '';
  return `• line ${row.input.source_line}: ${who}${person}${key}`;
}

const lines = [];
lines.push(`*${data.source}*: ${data.checked} row(s) checked.`);
lines.push(`${data.duplicate_count} already in the database, ${data.new_count} new, ${data.review_count} need a human.`);

if (duplicates.length) {
  lines.push('', '*Already on file:*');
  duplicates.slice(0, 5).forEach(row => lines.push(describe(row)));
  if (duplicates.length > 5) lines.push(`…and ${duplicates.length - 5} more`);
}

if (review.length) {
  lines.push('', '*Needs a human:*');
  review.slice(0, 5).forEach(row => {
    lines.push(describe(row) + (row.warnings.length ? `\n    ${row.warnings[0]}` : ''));
  });
  if (review.length > 5) lines.push(`…and ${review.length - 5} more`);
}

if (data.undeliverable_email_count) {
  lines.push('', `⚠️ ${data.undeliverable_email_count} address(es) are on RFC 2606 reserved domains and cannot receive mail.`);
}

return [{ json: {
  alert_text: lines.join('\n'),
  subject: `[ConsultBae] ${data.duplicate_count} duplicate + ${data.review_count} review in ${data.source}`,
  duplicate_count: data.duplicate_count,
  new_count: data.new_count,
  review_count: data.review_count,
  source: data.source
} }];

